            fullText: '玄都观里桃千树，花落水空流。凭君莫问，清泾浊渭，去马来牛。谢公扶病，羊昙挥涕，一醉都休。古今几度，生存华屋，零落山丘。元好问以哀乐中年，遭遇国难，既不肯随风偃仰，又无力回天，一腔怨愤，往往寄托于词。这种强烈灼人的情感，又往往通过放浪曲糵、潦倒狂笑的形象表现出来。清醒而作醉语，悲凉而作快语，更增其悲慨。郁郁块垒，凛凛英气，不是酒能浇化、醉能忘却的。',
