            fullText: '江上春山远，山下暮云长。相留相送，时见双燕语风樯。满目飞花万点，回首故人千里，把酒沃愁肠。回雁峰前路，烟树正苍苍。漏声残，灯焰短，马蹄香。浮云飞絮，一身将影向潇湘。多少风前月下，迤逦天涯海角，魂梦亦凄凉。又是春将暮，无语对斜阳。葛长庚，自名白玉蟾，南宋道士。陈廷焯《白雨斋词话》说他的词“风流凄楚，一片热肠，无方外习气”。',
