            fullText: '满洞苔钱。买断风烟。笑桃花流落晴川。石楼高处，夜夜啼猿。看二更云，三更月，四更天。细草如毡。独枕空拳。与山麋野鹿同眠。残霞未散，淡雾沈绵。是晋时人，唐时洞，汉时仙。（原注：洞府自唐尧时始开，至东晋葛稚川方来。及伪刘称汉，此时方显，遂兴观。） 葛长庚，自号白玉蟾，尝封为紫清真人。',
