            fullText: '天下事，问天怎忍如此。陵图谁把献君王，结愁未已。少豪气概总成尘，空馀白骨黄苇。千古恨，吾老矣。东游曾吊淮水。绣春台上一回登，一回揾泪。醉归抚剑倚西风，江涛犹壮人意。只今袖手野色里，望长淮、犹二千里。纵有英心谁寄。近新来又报胡尘起。绝域张骞归来未。王埜早年曾任两浙转运判官，以察访使名义巡视江防，增修兵船。以后任知镇江府、沿江制置使、江东安抚使等，设置水师水舰，致力于长江防务。以后拜端明殿学士，签书枢密院事，封吴郡侯。不久被劾，主管洞霄宫。存词三首。',
