            fullText: '寒食郓州道中 十五年来，逢寒食节，皆在天涯。叹雨濡露润，还思宰柏；风柔日媚，羞见飞花。麦饭纸钱，只鸡斗酒，几误林间噪喜鸦。天笑道：此不由乎我，也不由他。鼎中炼熟丹砂。把紫府清都作一家。想前人鹤驭，常游绛阙；浮生蝉蜕，岂恋黄沙。帝命守坟，王令修墓，男子正当如是耶。又何必，待过家上冢，昼锦荣华。宋亡之后，谢枋得隐居闽中，元朝廷累征不起。至元二十六年（1289），福建参知政事魏天祐，为取媚于朝廷，强执谢枋得北上。寒食节，过郓州（今山东郓城）；四月，枋得至燕京，绝食而卒，年六十四。',
