            fullText: '扫深殿，闭久金铺暗。游丝络网尘作堆，积岁青苔厚阶面。扫深殿，待君宴。拂象床，凭梦借高唐。敲坏半边知妾卧，恰当天处少辉光。拂象床，待君王。换香枕，一半无云锦。为是秋来展转①多，更有双双泪痕渗。换香枕，待君寝。铺翠被，羞杀鸳鸯对。犹忆当时叫合欢，而今独覆相思块。铺翠被，待君睡。装绣帐，金钩未敢上。解却四角夜光珠，不教照见愁模样。装绣帐，待君贶。叠锦茵，重重空自陈。只愿身当白玉体，不愿伊当薄命人。叠锦茵，待君临。展瑶席，花笑三韩碧。笑妾新铺玉一床，从来妇欢不终夕。展瑶席，待君息。剔银灯，须知一样明。偏是君来生彩晕，对妾故作青荧荧。剔银灯，待君行。爇熏炉，能将孤闷苏。若道妾身多秽贱，自沾御香香彻肤。爇熏炉，待君娱。张鸣筝，恰恰语娇莺。一从弹作房中曲，常和窗前风雨声。张鸣筝，待君听。萧观音的《回心院》词，共十首，见于辽王鼎《焚椒录》。',
